	private void delete(LocalFile file) {
		if (file.isDirectory()
				&& (file.getName().equals(".") || file.getName().equals(".."))) {
			return;
		}
		if (file.isFile()) {
			file.delete();
		} else if (file.isDirectory()) {
			LocalFile[] children = file.list(localFileFilter);
			for (int i = 0; i < children.length; i++) {
				delete(children[i]);
			}
			file.delete();
		}
	}

	public void executeCommand(final String command) {
		if (client == null || !client.isConnected()) {
			return;
		}
		setBusy(true);
		new SwingWorker() {

			@Override
			public Object construct() {
				try {
					client.executeCommand(command);
				} catch (FTPException exp) {
					ftpException(exp);
				} catch (ConnectionException exp) {
					connectionException(exp);
				} catch (Exception exp) {
					statusWindow.addError(exp.toString());
					exp.printStackTrace();
				} finally {
					return null;
				}
			}

			@Override
			public void finished() {
				setBusy(false);
			}
		}.start();
	}

	public void executeCommands(final String[] commands) {
		if (commands == null || client == null || !client.isConnected()) {
			return;
		}
		setBusy(true);
		new SwingWorker() {

			@Override
			public Object construct() {
				try {
					for (int i = 0; i < commands.length; i++) {
						String command = commands[i].toUpperCase();
						if (!(command.startsWith("LIST")
								|| command.startsWith("NLST")
								|| command.startsWith("RETR")
								|| command.startsWith("STOR")
								|| command.startsWith("STOU")
								|| command.startsWith("APPE")
								|| command.startsWith("PASV")
								|| command.startsWith("PORT")
								|| command.startsWith("DATA")
								|| command.startsWith("CWD") || command
									.startsWith("CDUP"))) {
							client.executeCommand(commands[i]);
						}
					}
				} catch (FTPException exp) {
					ftpException(exp);
				} catch (ConnectionException exp) {
					connectionException(exp);
				} catch (Exception exp) {
					statusWindow.addError(exp.toString());
					exp.printStackTrace();
				} finally {
					return null;
				}
			}

			@Override
			public void finished() {
				setBusy(false);
			}
		}.start();
	}

	public void disconnect() {
		if (client == null || !client.isConnected()) {
			return;
		}
		setBusy(true);
		new SwingWorker() {

			@Override
			public Object construct() {
				try {
					client.disconnect();
				} catch (FTPException exp) {
					ftpException(exp);
				} catch (ConnectionException exp) {
					connectionException(exp);
				} catch (Exception exp) {
					statusWindow.addError("<ERROR> " + exp);
					exp.printStackTrace();
				} finally {
					return null;
				}
			}

			@Override
			public void finished() {
				if (timer.isRunning()) {
					timer.stop();
				}
				statusBar.reset();
				bytesTransferred = 0L;
				timeElapsed = 0;
				remotePane.clearAll();
				updateTitle();
				setBusy(false);
			}
		}.start();
	}

	public boolean isConnected() {
		if (client == null) {
			return false;
		}
		return client.isConnected();
	}

